//! Explicit local-only toy installation for paired client/server evaluation.
//! Secrets are generated by the real enrollment flow and captured only in the
//! newly created private installation. Never print them or reuse this as remote enrollment.
#![deny(unsafe_code, clippy::unwrap_used, clippy::expect_used, clippy::panic)]
#[allow(dead_code)]
#[path = "../../solidcraft/src/pdm_credentials.rs"]
mod pdm_credentials;
#[allow(dead_code)]
#[path = "../src/service.rs"]
mod service;

use pdm_credentials::{CredentialContext, CredentialKey, CredentialStore, Purpose};
use serde::{Deserialize, Serialize};
use service::{Action, MemoryCredentials, Service};
use solidcraft_pdm::{
    AuthToken, Error, Request, Response, VersionRef,
    administration::{AdminRequest, AdminResponse},
    client::{Client, read_file},
    deployment::{DeploymentConfig, start_loopback_rehearsal},
    managed::{ManagedCheckIn, ManagedVersion, Role},
};
use std::{
    fs,
    io::Write,
    path::{Path, PathBuf},
};

const ADMIN: &str = "paired-admin";
const AUTHOR: &str = "paired-author";

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Account {
    principal_id: String,
    role: Role,
    bearer_path: PathBuf,
}
#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Descriptor {
    version: u32,
    origin: String,
    server_id: String,
    certificate_der_path: PathBuf,
    deployment_config: PathBuf,
    accounts: Vec<Account>,
}
fn publish(path: &Path, bytes: &[u8]) -> Result<(), Error> {
    let mut options = fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    let mut file = options.open(path)?;
    file.write_all(bytes)?;
    file.sync_all()?;
    Ok(())
}
fn prepare(root: &Path, stream_policy: Option<solidcraft_pdm::stream_io::StreamPolicy>) -> Result<(), Error> {
    let mut service = Service::new(MemoryCredentials::default());
    let create = match stream_policy {
        Some(stream_policy) => Action::CreateConfigured { root: root.to_owned(), administrator: ADMIN.into(), port: 0, stream_policy },
        None => Action::Create { root: root.to_owned(), administrator: ADMIN.into(), port: 0 },
    };
    service.perform(create)?;
    service.perform(Action::CreateUser { id: AUTHOR.into(), role: Role::Contributor })?;
    let snapshot = service.snapshot.clone();
    let certificate_der_path = root.join("tls/certificate.der");
    let der = read_file(&certificate_der_path, 64 * 1024)?;
    let context = CredentialContext::certificate_der(&der, None).map_err(|_| Error::Integrity)?;
    let mut accounts = Vec::new();
    for (id, role) in [(ADMIN, Role::Administrator), (AUTHOR, Role::Contributor)] {
        let key = CredentialKey::new_scoped(&snapshot.origin, &snapshot.server_id, id, Purpose::User, &context).map_err(|_| Error::Integrity)?;
        let secret = service.credentials.get(&key).map_err(|_| Error::Integrity)?.ok_or(Error::Integrity)?;
        let bearer_path = root.join(format!("{id}.bearer"));
        publish(&bearer_path, secret.expose().as_bytes())?;
        accounts.push(Account { principal_id: id.into(), role, bearer_path });
    }
    service.perform(Action::Stop)?;
    let installation: service::Installation = serde_json::from_slice(&read_file(&root.join("console.json"), 16 * 1024)?)?;
    let config = DeploymentConfig {
        store: root.join("archive"),
        bind: (std::net::Ipv4Addr::LOCALHOST, installation.port).into(),
        certificate_chain: vec![certificate_der_path.clone()],
        private_key: root.join("tls/private-key.der"),
    };
    let deployment_config = root.join("deployment.json");
    publish(&deployment_config, &serde_json::to_vec_pretty(&config)?)?;
    let descriptor =
        Descriptor { version: 1, origin: snapshot.origin, server_id: snapshot.server_id, certificate_der_path, deployment_config, accounts };
    // Publish the public handoff only after the two private captures and shutdown.
    publish(&root.join("paired-descriptor.json"), &serde_json::to_vec_pretty(&descriptor)?)?;
    println!("Prepared private paired fixture; no server remains running.");
    Ok(())
}
fn connect(root: &Path, descriptor: &Descriptor, id: &str) -> Result<Client, Error> {
    if descriptor.version != 1
        || descriptor.certificate_der_path != root.join("tls/certificate.der")
        || descriptor.deployment_config != root.join("deployment.json")
    {
        return Err(Error::Integrity);
    }
    let config = DeploymentConfig::load(&descriptor.deployment_config)?;
    if config.store != root.join("archive")
        || descriptor.origin != format!("https://127.0.0.1:{}", config.bind.port())
        || config.bind.ip() != std::net::Ipv4Addr::LOCALHOST
    {
        return Err(Error::Integrity);
    }
    let account = descriptor.accounts.iter().find(|account| account.principal_id == id).ok_or(Error::Integrity)?;
    if account.bearer_path != root.join(format!("{id}.bearer")) {
        return Err(Error::Integrity);
    }
    let secret = String::from_utf8(read_file(&account.bearer_path, 64)?).map_err(|_| Error::Integrity)?;
    let der = read_file(&descriptor.certificate_der_path, 64 * 1024)?;
    let client = Client::https_with_ca(&descriptor.origin, AuthToken::parse(secret)?, &der)?.bind_server(&descriptor.server_id)?;
    let identity = client.authenticated_identity()?;
    if identity.principal.id != id || identity.principal.role != account.role {
        return Err(Error::Integrity);
    }
    Ok(client)
}
fn check_in(
    client: &Client,
    document: &str,
    parent: Option<u64>,
    content: &[u8],
    dependencies: Vec<VersionRef>,
    request: &str,
) -> Result<ManagedVersion, Error> {
    let grant = client.managed_checkout(document.into(), "paired-proof".into(), "owned-proof".into())?;
    client.managed_check_in(ManagedCheckIn {
        document: document.into(),
        workspace: "paired-proof".into(),
        machine: "owned-proof".into(),
        checkout_token: grant.token,
        request_id: request.into(),
        parent,
        content: content.to_vec(),
        dependencies,
        comment: "Disposable paired contract proof".into(),
    })
}
fn proof(root: &Path) -> Result<(), Error> {
    let descriptor: Descriptor = serde_json::from_slice(&read_file(&root.join("paired-descriptor.json"), 16 * 1024)?)?;
    let server = start_loopback_rehearsal(DeploymentConfig::load(&root.join("deployment.json"))?)?;
    let admin = connect(root, &descriptor, ADMIN)?;
    let author = connect(root, &descriptor, AUTHOR)?;
    let capabilities = admin.capabilities()?;
    if capabilities.metadata_backend != "redb"
        || !capabilities.features.users_admin_v1
        || !matches!(author.admin(AdminRequest::ListUsers {}), Err(Error::Server(code)) if code == "forbidden")
    {
        return Err(Error::Integrity);
    }
    if !matches!(admin.admin(AdminRequest::ListUsers {})?, AdminResponse::Users { users, .. } if users.len() == 2) {
        return Err(Error::Integrity);
    }
    let part = author.managed_create("contract-proof/part.txt".into())?;
    let v1 = check_in(&author, &part.document, None, b"part one", vec![], "paired-part-one")?;
    let assembly = admin.managed_create("contract-proof/assembly.txt".into())?;
    let assembly_v1 =
        check_in(&admin, &assembly.document, None, b"assembly pins part one", vec![v1.version.reference.clone()], "paired-assembly-one")?;
    let grant = author.managed_checkout(part.document.clone(), "paired-proof".into(), "owned-proof".into())?;
    if !matches!(admin.managed_checkout(part.document.clone(), "other-workspace".into(), "other-machine".into()), Err(Error::Server(code)) if code == "conflict")
    {
        return Err(Error::Integrity);
    }
    server.shutdown()?;
    let server = start_loopback_rehearsal(DeploymentConfig::load(&root.join("deployment.json"))?)?;
    let author = connect(root, &descriptor, AUTHOR)?;
    let resumed = author.managed_resume_checkout(part.document.clone(), "paired-proof".into(), "owned-proof".into())?;
    if resumed.token != grant.token {
        return Err(Error::Integrity);
    }
    let v2 = author.managed_check_in(ManagedCheckIn {
        document: part.document.clone(),
        workspace: "paired-proof".into(),
        machine: "owned-proof".into(),
        checkout_token: resumed.token,
        request_id: "paired-part-two".into(),
        parent: Some(1),
        content: b"part two".to_vec(),
        dependencies: vec![],
        comment: "Second disposable version".into(),
    })?;
    if v2.version.reference.version != 2
        || author.managed_history(part.document.clone())?.len() != 2
        || author.download(&v1.version.reference)?.1 != b"part one"
        || author.download(&assembly_v1.version.reference)?.0.dependencies != vec![v1.version.reference.clone()]
        || !matches!(author.request(Request::WhereUsed { reference: v1.version.reference.clone() })?, Response::WhereUsed { versions } if versions.contains(&assembly_v1.version.reference))
    {
        return Err(Error::Integrity);
    }
    server.shutdown()?;
    let server = start_loopback_rehearsal(DeploymentConfig::load(&root.join("deployment.json"))?)?;
    if connect(root, &descriptor, ADMIN)?.managed_history(part.document)?.len() != 2 {
        return Err(Error::Integrity);
    }
    server.shutdown()?;
    println!(
        "PASS redb pinned TLS, two identities, contributor admin denial, exclusive checkout, persisted lease, v1/v2 history, pinned references and two restarts; owned server stopped."
    );
    Ok(())
}
fn run() -> Result<(), Box<dyn std::error::Error>> {
    let _ = rustls::crypto::ring::default_provider().install_default();
    let args: Vec<String> = std::env::args().skip(1).collect();
    let root = Path::new(args.get(1).ok_or("paired fixture root required")?);
    if args.len() != 2 || !root.is_absolute() {
        return Err("usage: paired_fixture prepare NEW_ABSOLUTE_ROOT | proof OWNED_FIXTURE_ROOT".into());
    }
    match args.first().map(String::as_str) {
        Some("prepare") => prepare(root, None)?,
        Some("prepare-stream") => prepare(
            root,
            Some(solidcraft_pdm::stream_io::StreamPolicy { version: 1, max_file_bytes: 8 * 1024 * 1024, max_store_bytes: 20 * 1024 * 1024 * 1024 }),
        )?,
        Some("proof") => proof(root)?,
        _ => return Err("unknown paired fixture operation".into()),
    }
    Ok(())
}
fn main() -> std::process::ExitCode {
    match run() {
        Ok(()) => std::process::ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("Paired fixture failed: {error}");
            std::process::ExitCode::FAILURE
        }
    }
}
